import {Component, Inject} from "@angular/core";
import {BaseUpsertComponentV3} from "../../../../../../../base/components/base-upsert-v3.component";
import {defaultTaskConfig, selfEndpoints, selfRoutes, TaskConfig} from "../../models/config.model";
import {ITaskState} from "../../../taskstates/models/taskstate.model";
import {ITask, ITaskActivity, ITaskDetail, ITaskReq} from "../../models/task.model";
import {AbstractControl, FormControl, FormGroup, ValidatorFn, Validators} from "@angular/forms";
import {EventBusService} from "../../../../../../../services/eventbus/event-bus.service";
import {ActivatedRoute, Router} from "@angular/router";
import {SubscriptionContainerService} from "../../../../../../../base/services/subscription-container.service";
import {TaskService} from "../../services/task.service";
import {NotifierService} from "../../../../../../../services/notifier/notifier.service";
import {AuthService} from "../../../../../../common/modules/auth/services/auth.service";
import {BreadcrumbItem} from "../../../../../../common/modules/generic/breadcrumb/breadcrumb.model";
import {EventKey} from "../../../../../../../services/eventbus/event.key";
import {HttpErrorResponse} from "@angular/common/http";
import {IImageSlice} from "../../../../../../common/modules/cms/files/models/file.model";
import {BaseConfigV2} from "../../../../../../../base/models/baseConfig";
import {MAT_DIALOG_DATA} from "@angular/material/dialog";
import {IBoard} from "../../../boards/models/board.model";
import {translations} from "../../../../../layout/left-nav/menu.model";
import {Utility} from "../../../../../../common/modules/utility/utility";
import {ITaskAssignment, ITaskAssignmentDetail} from "../../../taskassignments/models/taskassignment.model";
import {
  TaskAssignmentUpsertComponent
} from "../../../taskassignments/components/taskassignment-upsert/taskassignment-upsert.component";
import {DialogService} from "../../../../../../common/modules/utility/components/popup/dialog.service";
import {IParams} from "../../../../../../../base/endpoints/iparams";
import {defaultPage, IPage} from "../../../../../../../base/models/IPage";


@Component({
  selector: 'app-task-upsert',
  templateUrl: './task-upsert.component.html',
  styleUrls: ['./task-upsert.component.scss']
})
export class TaskUpsertComponent extends BaseUpsertComponentV3<ITaskDetail> {

  config: TaskConfig = defaultTaskConfig

  selectedState: ITaskState | null = null
  selectedParent: ITask | null = null
  selectedBoard: IBoard | null = null

  isAdmin = false
  edit = true
  taskDetail: ITaskDetail | null = null
  startAt: string | null = null
  endAt: string | null = null

  activities: IPage<ITaskActivity> = defaultPage

  taskForm = new FormGroup({
    title: new FormControl<string | null>('', [Validators.required, Validators.minLength(3)]),
    description: new FormControl<string | null>(null, []),
    repeated: new FormControl(false, []),
    image: new FormControl<string | null>(null),
    state_id: new FormControl<number | null>(null, [Validators.required]),
    milestone_id: new FormControl<number | null>(null, []),
    parent_id: new FormControl<number | null>(null, []),
    board_id: new FormControl<number | null>(null, [this.requiredIFNotAdminValidation()]),
  })

  constructor(eventBus: EventBusService,
              router: Router,
              subContainer: SubscriptionContainerService,
              route: ActivatedRoute,
              private taskService: TaskService,
              private notifier: NotifierService,
              authService: AuthService,
              @Inject(MAT_DIALOG_DATA) dialogData: any,
              private assignmentDialog: DialogService<ITaskAssignmentDetail>) {
    super(eventBus, router, subContainer, route, dialogData)

    if (authService.isAdmin()) {
      this.isAdmin = true
      this.config.endpoint = selfEndpoints.adminEndpoint
      this.config.delEndpoint = selfEndpoints.adminEndpoint
    }

    this.taskForm.controls.title.setValue(dialogData.title)

    if (dialogData.edit != null) {
      this.edit = dialogData.edit
    }

    let board = dialogData.board as IBoard
    if (board != null) {
      this.selectedBoard = board
      this.taskForm.controls.board_id.setValue(board.id)
    }

    let state = dialogData.state as ITaskState
    if (state != null) {
      this.selectedState = state
      this.taskForm.controls.state_id.setValue(state.id)
    }

  }

  protected override componentName(): string {
    return TaskUpsertComponent.name
  }

  protected override getBreadcrumbItems(): BreadcrumbItem[] {
    return [
      {
        text: this.translations["Dashboard"],
        link: null,
        active: false
      },
      {
        text: translations["Task"],
        link: "/dash/tasks",
        active: false
      },
      {
        text: translations["Upsert"],
        link: null,
        active: true
      }
    ]
  }

  override initialize(exId: number): void {
    this.loading = true
    let key = this.componentKey(EventKey.TASKS.GET(exId))
    this.taskService.fetchSingle(key, this.config.endpoint, exId)
    this.subscribe(key, null, (value, meta) => {
      this.loading = false;
      this.taskDetail = meta.data as ITaskDetail
      this.populateForm(this.taskDetail)
      if (!this.edit) {
        this.loadTaskActivities(this.taskDetail.id, {
          page: 0,
          size: 50
        })
      }
    })
    this.subscribe(this.getErrorKey(key), null, (value, meta) => {
      let error: HttpErrorResponse = meta.data
      console.log(error)
      this.loading = false;
    })
  }

  onSubmit() {
    if (!this.taskForm.valid) {
      return
    }
    this.upsert(this.exId)
  }

  onImgUploaded(images: IImageSlice[]) {
    if (images.length > 0) {
      /*
      Think about the thumbnail, this will only upload the image, not thumbnail
       */
      this.taskForm.controls.image.setValue(images[0].image_url)
    }
  }

  getExImages(): IImageSlice[] {
    let image = this.taskForm.controls.image.value
    if (image == null) {
      return []
    }
    return [{image_url: image, thumb_url: image}]
  }

  getConfig(): BaseConfigV2 {
    return this.config;
  }

  getListPageRoute(): string {
    return selfRoutes.list;
  }

  upsert(exId: number | null) {
    this.loading = true
    let key = this.componentKey(EventKey.TASKS.UPSERT(exId))
    let req = this.taskForm.value as ITaskReq
    this.taskService.upsert(key, this.config.endpoint, req, exId)
    this.subscribe(key, null, (value, meta) => {
      this.notifier.success("Success", "Task has been " + (exId ? "updated" : "created"))
      this.taskForm.reset();
      this.onSuccess(meta.data)
    })
    this.subscribe(this.getErrorKey(key), null, (value, meta) => {
      let error: HttpErrorResponse = meta.data
      this.loading = false;
      this.notifier.warning('Failed!', error.error.message)
    })
  }

  private populateForm(n: ITaskDetail) {
    this.selectedParent = n.parent
    this.selectedBoard = n.board
    this.selectedState = n.state

    this.taskForm.controls.title.setValue(n.title)
    this.taskForm.controls.description.setValue(n.description)
    this.taskForm.controls.repeated.setValue(n.repeated)
    this.taskForm.controls.image.setValue(n.image)
    this.taskForm.controls.state_id.setValue(n.state.id)
    this.taskForm.controls.milestone_id.setValue(n.milestone_id)
    this.taskForm.controls.board_id.setValue(n.board?.id ?? null)
    this.taskForm.controls.parent_id.setValue(n.parent_id)
  }

  onStateSelected(state: ITaskState | null) {
    this.selectedState = state
    this.taskForm.controls.state_id.setValue(state?.id ?? null)
  }

  onParentSelected(task: ITask | null) {
    this.selectedParent = task
    this.taskForm.controls.parent_id.setValue(task?.id ?? null)
  }

  onBoardSelected(board: IBoard | null) {
    this.selectedBoard = board
    this.taskForm.controls.board_id.setValue(board?.id ?? null)
  }

  requiredIFNotAdminValidation(): ValidatorFn {
    return (control: AbstractControl): { [key: string]: boolean } | null => {
      const value: number = control.value || null;

      const valid = this.isAdmin ? true : value != null;
      return valid ? null : {'required': true};
    };
  }

  protected readonly Utility = Utility;

  getDescription(description: string | null | undefined) {
    return description == null || description.length === 0 ? 'No description provided' : description;
  }

  upsertAssignment(event: Event, task: ITask, assignment: ITaskAssignment | null) {
    event.stopPropagation()
    this.assignmentDialog.open(TaskAssignmentUpsertComponent, {id: null, task: task, assignee: assignment?.assignee})
    this.assignmentDialog.onCompleted.subscribe((result: ITask | null) => {
      this.ngOnInit()
    })
    this.assignmentDialog.onCanceled.subscribe(() => {
    })
  }

  buildTask(taskDetail: ITaskDetail): ITask {
    return {
      id: taskDetail.id,
      created_by: taskDetail.created_by,
      created_at: taskDetail.created_at,
      updated_at: taskDetail.updated_at,
      title: taskDetail.title,
      description: taskDetail.description,
      image: taskDetail.image,
      start_at: taskDetail.start_at,
      end_at: taskDetail.end_at,
      repetitive: false,
      state: taskDetail.state,
      parent_id: taskDetail.parent_id,
      board_id: taskDetail.board?.id ?? null,
      board_title: taskDetail.board?.title ?? null,
      milestone_id: taskDetail.milestone_id,
      assignments: taskDetail.assignments.map(ad => {
        return {
          id: ad.id,
          created_by: ad.created_by,
          created_at: ad.created_at,
          updated_at: ad.updated_at,
          task_id: ad.task.id,
          event_id: ad.event?.id ?? null,
          assignee: ad.assignee,
        }
      }),
    }
  }

  removeAssignment(task: ITask, assignment: ITaskAssignment) {
    if (!confirm("Are you sure you wanna remove this assignment?")) return
    let key = this.componentKey(EventKey.TASKS.REMOVE_ASSIGNMENT(task.id, assignment.assignee.id))
    this.taskService.remove(key, task.id, assignment.assignee.id)
    this.subscribe(key, null, (v, meta) => {
      let removed = meta.data as Boolean
      if (removed) {
        this.notifier.success("Removed", "Successfully removed assignment.")
        this.ngOnInit()
      } else {
        this.notifier.warning("Failed", "Couldn't remove assignment.")
      }
    })
    this.subscribe(this.getErrorKey(key), null, (value, meta) => {
      let err: HttpErrorResponse = meta.data
      this.notifier.error('Error!', err.error.error.message)
    })
    console.log("task", task, "assignment", assignment)
  }

  protected readonly Date = Date;

  loadTaskActivities(taskId: number, params: IParams) {
    this.loading = true
    let key = this.componentKey(EventKey.TASKS.SEARCH_ACTIVITIES(taskId))
    this.taskService.searchTaskActivities(key, taskId, params)
    this.subscribe(key, null, (value, meta) => {
      this.loading = false
      this.activities = meta.data
    })
    this.subscribe(this.getErrorKey(key), null, (value, meta) => {
      let err: HttpErrorResponse = meta.data
      this.notifier.error('Error!', err.error.error.message)
    })
  }
}
