import {Component, Inject} from "@angular/core";
import {BaseUpsertComponentV3} from "../../../../../../../base/components/base-upsert-v3.component";
import {defaultTaskStateConfig, selfEndpoints, selfRoutes, TaskStateConfig} from "../../models/config.model";
import {FormControl, FormGroup, Validators} from "@angular/forms";
import {EventBusService} from "../../../../../../../services/eventbus/event-bus.service";
import {ActivatedRoute, Router} from "@angular/router";
import {SubscriptionContainerService} from "../../../../../../../base/services/subscription-container.service";
import {TaskStateService} from "../../services/taskstate.service";
import {NotifierService} from "../../../../../../../services/notifier/notifier.service";
import {AuthService} from "../../../../../../common/modules/auth/services/auth.service";
import {BreadcrumbItem} from "../../../../../../common/modules/generic/breadcrumb/breadcrumb.model";
import {EventKey} from "../../../../../../../services/eventbus/event.key";
import {HttpErrorResponse} from "@angular/common/http";
import {IImageSlice} from "../../../../../../common/modules/cms/files/models/file.model";
import {BaseConfigV2} from "../../../../../../../base/models/baseConfig";
import {ITaskStateDetail, ITaskStateReq} from "../../models/taskstate.model";
import {MAT_DIALOG_DATA} from "@angular/material/dialog";
import {IBoard} from "../../../boards/models/board.model";
import {TextUtility} from "../../../../../../common/modules/utility/text.utility";


@Component({
  selector: 'app-taskstate-upsert',
  templateUrl: './taskstate-upsert.component.html',
  styleUrls: ['./taskstate-upsert.component.scss']
})
export class TaskStateUpsertComponent extends BaseUpsertComponentV3<ITaskStateDetail> {

  config: TaskStateConfig = defaultTaskStateConfig

  selectedBoard: IBoard | null = null

  taskStateForm = new FormGroup({
    label: new FormControl('', [Validators.required, Validators.minLength(3)]),
    state: new FormControl('', [Validators.required, Validators.minLength(3)]),
    image: new FormControl<string | null>(null),
    color: new FormControl<string | null>(null, []),
    order: new FormControl<number | null>(null, [Validators.required]),
    board_id: new FormControl<number | null>(null, [Validators.required]),
  })

  constructor(eventBus: EventBusService,
              router: Router,
              subContainer: SubscriptionContainerService,
              route: ActivatedRoute,
              private taskStateService: TaskStateService,
              private notifier: NotifierService,
              authService: AuthService,
              @Inject(MAT_DIALOG_DATA) dialogData: any) {
    super(eventBus, router, subContainer, route, dialogData)

    if (authService.isAdmin()) {
      this.config.endpoint = selfEndpoints.adminEndpoint
      this.config.delEndpoint = selfEndpoints.adminEndpoint
    }

    if (dialogData.title != null) {
      this.taskStateForm.controls.label.setValue(dialogData.title)
    }

  }

  override ngOnInit() {
    super.ngOnInit();
    this.taskStateForm.controls.label.valueChanges.subscribe(value => {
      this.taskStateForm.controls.state.setValue(TextUtility.codify(value))
    })
  }

  protected override componentName(): string {
    return TaskStateUpsertComponent.name
  }

  protected override getBreadcrumbItems(): BreadcrumbItem[] {
    return [
      {
        text: this.translations["Dashboard"],
        link: null,
        active: false
      },
      {
        text: "TaskStates",
        link: "/dash/taskstates",
        active: false
      },
      {
        text: "Upsert",
        link: null,
        active: true
      }
    ]
  }

  override initialize(exId: number): void {
    this.loading = true
    let key = this.componentKey(EventKey.TASKSTATES.GET(exId))
    this.taskStateService.fetchSingle(key, this.config.endpoint, exId)
    this.subscribe(key, null, (value, meta) => {
      this.loading = false;
      this.populateForm(meta.data)
    })
    this.subscribe(this.getErrorKey(key), null, (value, meta) => {
      let error: HttpErrorResponse = meta.data
      console.log(error)
      this.loading = false;
    })
  }

  onSubmit() {
    if (!this.taskStateForm.valid) {
      return
    }
    this.upsert(this.exId)
  }

  onImgUploaded(images: IImageSlice[]) {
    if (images.length > 0) {
      /*
      Think about the thumbnail, this will only upload the image, not thumbnail
       */
      this.taskStateForm.controls.image.setValue(images[0].image_url)
    }
  }

  getExImages(): IImageSlice[] {
    let image = this.taskStateForm.controls.image.value
    if (image == null) {
      return []
    }
    return [{image_url: image, thumb_url: image}]
  }

  getConfig(): BaseConfigV2 {
    return this.config;
  }

  getListPageRoute(): string {
    return selfRoutes.list;
  }

  upsert(exId: number | null) {
    this.loading = true
    let key = this.componentKey(EventKey.TASKSTATES.UPSERT(exId))
    let req = this.taskStateForm.value as ITaskStateReq
    this.taskStateService.upsert(key, this.config.endpoint, req, exId)
    this.subscribe(key, null, (value, meta) => {
      this.notifier.success("Success", "TaskState has been " + (exId ? "updated" : "created"))
      this.taskStateForm.reset();
      this.onSuccess(meta.data)
    })
    this.subscribe(this.getErrorKey(key), null, (value, meta) => {
      let error: HttpErrorResponse = meta.data
      this.loading = false;
      this.notifier.warning('Failed!', error.error.message)
    })
  }

  private populateForm(n: ITaskStateDetail) {
    this.selectedBoard = n.board
    this.taskStateForm.controls.label.setValue(n.label)
    this.taskStateForm.controls.state.setValue(n.state)
    this.taskStateForm.controls.image.setValue(n.image == null ? null : n.image)
    this.taskStateForm.controls.color.setValue(n.color)
    this.taskStateForm.controls.order.setValue(n.order)
    this.taskStateForm.controls.board_id.setValue(n.board?.id ?? null)
  }

  onBoardSelected(board: IBoard | null) {
    this.selectedBoard = board
    this.taskStateForm.controls.board_id.setValue(board?.id ?? null)
  }
}
