import {Component, EventEmitter, Input, Output} from '@angular/core';
import {EventBusService} from "../../../../../../../services/eventbus/event-bus.service";
import {Router} from "@angular/router";
import {SubscriptionContainerService} from "../../../../../../../base/services/subscription-container.service";
import {AuthService} from "../../../../../../common/modules/auth/services/auth.service";
import {EmployeeService} from "../../../../hr/employees/services/employee.service";
import {DialogService} from "../../../../../../common/modules/utility/components/popup/dialog.service";
import {TextUtility} from "../../../../../../common/modules/utility/text.utility";
import {IUserBrief} from "../../../../users/users/models/user.model";
import {IParams} from "../../../../../../../base/endpoints/iparams";
import {EventKey} from "../../../../../../../services/eventbus/event.key";
import {UserEndpoints} from "../../../../users/user.endpoint";
import {HrEndpoints} from "../../../../hr/hr.endpoints";
import {IEmployee} from "../../../../hr/employees/models/employee.model";
import {selfEndpoints} from "../../models/config.model";
import {UserService} from "../../../../users/users/services/user.service";
import {IAssignee} from "../../../taskassignments/models/taskassignment.model";
import {OrganizationService} from "../../../../mdm/organizations/services/organization.service";
import {BaseComponentForOrg} from "../../../../mdm/organizations/components/org-base-select.component";

@Component({
  selector: 'app-assignee-select',
  templateUrl: './assignee-select.component.html',
  styleUrls: ['./assignee-select.component.scss']
})
export class AssigneeSelectComponent extends BaseComponentForOrg {
  @Input() enableAdd: boolean = true

  @Input() searchEndpoint: string = selfEndpoints.endpoint

  items: IAssignee[] = []

  @Input() label: string = "Assignee"
  @Input() selectedItem: IAssignee | null = null
  @Output() selected: EventEmitter<IAssignee | null> = new EventEmitter<IAssignee | null>()

  protected override componentName(): string {
    return AssigneeSelectComponent.name;
  }

  constructor(eventBus: EventBusService,
              router: Router,
              subContainer: SubscriptionContainerService,
              private authService: AuthService,
              private userService: UserService,
              private employeeService: EmployeeService,
              private popupService: DialogService<IUserBrief>,
              organizationService: OrganizationService) {
    super(eventBus, router, subContainer, organizationService)

    if (authService.isAdmin()) {
      this.searchEndpoint = selfEndpoints.adminEndpoint
    }
  }

  override ngOnInit(): void {
    this.loading = false
    this.search({
      page: 0, size: 10, q: null
    })
  }

  searchForEvent(event: any) {
    let query = TextUtility.removeSpecialCharacters(event.target?.value)
    if (query.length > 2) {
      this.search({
        page: 0, size: 10, q: query
      })
    }
  }

  onSelected(event: any) {
    if (event == null) {
      this.selected.emit(null)
    } else if (this.items.find(c => c.username == event.username)) {
      let user = (event as IUserBrief)
      this.selectedItem = {
        id: user.id,
        name: user.name,
        username: user.username,
        avatar: user.avatar
      }
      this.selected.emit(this.selectedItem)
    } else {
      // let popup = this.popupService.open(
      //   UserUpsertComponent, {id: null, title: event.title}
      // )
      // popup.componentInstance.onCompleted.subscribe((user: IUserBrief | null) => {
      //     this.selected.emit(user)
      //   }
      // )
    }
  }

  search(params: IParams) {
    this.loading = true
    if (this.authService.isAdmin()) {
      let key = this.componentKey(EventKey.USERS.SEARCH(params))
      this.userService.search(key, UserEndpoints.USERS.USER_ENDPOINT_ADMIN, params)
      this.subscribe(key, null, (value, meta) => {
        let users = meta.data.content as IUserBrief[]
        this.items = users.map(u => {
          return {
            id: u.id,
            name: u.name,
            username: u.username,
            avatar: u.avatar
          }
        })
        this.loading = false
      })
    } else {
      this.onOrgLoaded((orgId: number) => {
        let key = this.componentKey(EventKey.EMPLOYEES.SEARCH(params))
        this.employeeService.search(key, HrEndpoints.EMPLOYEES.EMPLOYEE_ENDPOINT, {
          ...params,
          org_id: orgId
        })
        this.subscribe(key, null, (value, meta) => {
          let employees = meta.data.content as IEmployee[]
          this.items = employees.map(u => {
            return {
              id: u.id,
              name: u.name,
              username: u.user_full_name,
              avatar: u.image ?? ''
            }
          })
          this.loading = false
        })

      })
    }
  }

}
