import {Component, Inject} from '@angular/core';
import {FormControl, FormGroup, Validators} from "@angular/forms";
import {BaseUpsertComponentV3} from "../../../../../../../base/components/base-upsert-v3.component";
import {defaultTaskAssignmentConfig, selfEndpoints, selfRoutes, TaskAssignmentConfig} from "../../models/config.model";
import {EventBusService} from "../../../../../../../services/eventbus/event-bus.service";
import {ActivatedRoute, Router} from "@angular/router";
import {SubscriptionContainerService} from "../../../../../../../base/services/subscription-container.service";
import {TaskAssignmentService} from "../../services/taskassignment.service";
import {NotifierService} from "../../../../../../../services/notifier/notifier.service";
import {AuthService} from "../../../../../../common/modules/auth/services/auth.service";
import {MAT_DIALOG_DATA} from "@angular/material/dialog";
import {BreadcrumbItem} from "../../../../../../common/modules/generic/breadcrumb/breadcrumb.model";
import {EventKey} from "../../../../../../../services/eventbus/event.key";
import {HttpErrorResponse} from "@angular/common/http";
import {BaseConfigV2} from "../../../../../../../base/models/baseConfig";
import {IAssignee, ITaskAssignmentDetail, ITaskAssignmentReq} from "../../models/taskassignment.model";
import {ITask} from "../../../tasks/models/task.model";
import {translations} from "../../../../../layout/left-nav/menu.model";
import {TimeUtility} from "../../../../../../common/modules/utility/time.utility";

@Component({
  selector: 'app-taskassignment-upsert',
  templateUrl: './taskassignment-upsert.component.html',
  styleUrls: ['./taskassignment-upsert.component.scss']
})
export class TaskAssignmentUpsertComponent extends BaseUpsertComponentV3<ITaskAssignmentDetail> {

  config: TaskAssignmentConfig = defaultTaskAssignmentConfig

  selectedTask: ITask | null = null
  selectedAssignee: IAssignee | null = null

  reminder = false

  taskAssignmentForm = new FormGroup({
    task_id: new FormControl<number | null>(null, [Validators.required]),
    assignee_id: new FormControl<number | null>(null, [Validators.required]),
    event: new FormGroup({
      start_at: new FormControl<Date | null>(null, []),
      end_at: new FormControl<Date | null>(null, []),
      show_end_date: new FormControl<boolean>(false)
    })
  })

  constructor(eventBus: EventBusService,
              router: Router,
              subContainer: SubscriptionContainerService,
              route: ActivatedRoute,
              private taskAssignmentService: TaskAssignmentService,
              private notifier: NotifierService,
              authService: AuthService,
              @Inject(MAT_DIALOG_DATA) dialogData: any) {
    super(eventBus, router, subContainer, route, dialogData)

    if (authService.isAdmin()) {
      this.config.endpoint = selfEndpoints.adminEndpoint
      this.config.delEndpoint = selfEndpoints.adminEndpoint
    }

    if (dialogData.task != null) {
      this.selectedTask = dialogData.task as ITask
      this.taskAssignmentForm.controls.task_id.setValue(this.selectedTask.id)
    }

    if (dialogData.assignee != null) {
      this.selectedAssignee = dialogData.assignee as IAssignee
      this.taskAssignmentForm.controls.assignee_id.setValue(this.selectedAssignee.id)
    }

  }

  protected override componentName(): string {
    return TaskAssignmentUpsertComponent.name
  }

  protected override getBreadcrumbItems(): BreadcrumbItem[] {
    return [
      {
        text: this.translations["Dashboard"],
        link: null,
        active: false
      },
      {
        text: translations["TaskAssignment"],
        link: "/dash/task-assignments",
        active: false
      },
      {
        text: translations["Upsert"],
        link: null,
        active: true
      }
    ]
  }

  override initialize(exId: number): void {
    this.loading = true
    let key = this.componentKey(EventKey.TASKASSIGNMENTS.GET(exId))
    this.taskAssignmentService.fetchSingle(key, this.config.endpoint, exId)
    this.subscribe(key, null, (value, meta) => {
      this.loading = false;
      this.populateForm(meta.data)
    })
    this.subscribe(this.getErrorKey(key), null, (value, meta) => {
      let error: HttpErrorResponse = meta.data
      console.log(error)
      this.loading = false;
    })
  }

  onSubmit() {
    if (!this.taskAssignmentForm.valid) {
      return
    }
    this.upsert(this.exId)
  }

  getConfig(): BaseConfigV2 {
    return this.config;
  }

  getListPageRoute(): string {
    return selfRoutes.list;
  }

  upsert(exId: number | null) {
    let key = this.componentKey(EventKey.TASKASSIGNMENTS.UPSERT(exId))
    let req = this.taskAssignmentForm.value as ITaskAssignmentReq
    if (!this.reminder) {
      req.event = null
    } else {
      if (req.event?.start_at == null) {
        this.notifier.warning("Reminder time", "Reminder date time must be specified")
        return
      }
      req.event = {
        start_at: TimeUtility.toISO(req.event?.start_at ?? new Date()),
        end_at: req.event?.end_at == null || !this.taskAssignmentForm.controls.event.controls.show_end_date
          ? null : TimeUtility.toISO(req.event?.end_at)
      }
    }

    this.loading = true
    this.taskAssignmentService.upsert(key,  req, exId)
    this.subscribe(key, null, (value, meta) => {
      this.notifier.success("Success", "TaskAssignment has been " + (exId ? "updated" : "created"))
      this.taskAssignmentForm.reset();
      this.onSuccess(meta.data)
    })
    this.subscribe(this.getErrorKey(key), null, (value, meta) => {
      let error: HttpErrorResponse = meta.data
      this.loading = false;
      this.notifier.warning('Failed!', error.error.message)
    })
  }

  private populateForm(n: ITaskAssignmentDetail) {
    this.selectedTask = n.task
    this.selectedAssignee = n.assignee
    this.reminder = n.event != null
    this.taskAssignmentForm.controls.task_id.setValue(n.task.id)
    this.taskAssignmentForm.controls.assignee_id.setValue(n.assignee.id)

    this.taskAssignmentForm.controls.event.controls.start_at.setValue(
      n.event?.start_at == null ? null : TimeUtility.toISO(n.event?.start_at)
    )
    this.taskAssignmentForm.controls.event.controls.show_end_date.setValue(n.event?.end_at != null)
    this.taskAssignmentForm.controls.event.controls.end_at.setValue(
      n.event?.end_at == null ? null : TimeUtility.toISO(n.event?.end_at)
    )
  }

  onTaskSelected(task: ITask | null) {
    this.selectedTask = task
    this.taskAssignmentForm.controls.task_id.setValue(task?.id ?? null)
  }

  onAssigneeSelected(assignee: IAssignee | null) {
    this.selectedAssignee = assignee
    this.taskAssignmentForm.controls.assignee_id.setValue(assignee?.id ?? null)
  }

  showReminder(show: boolean) {
    this.reminder = show
  }

  isSelectedTaskRepetitive(): boolean {
    return this.selectedTask?.repetitive ?? false
  }
}
