import {BaseListComponentV4} from "../../../../../../base/components/base-list-v4.component";
import {EventBusService} from "../../../../../../services/eventbus/event-bus.service";
import {Router} from "@angular/router";
import {SubscriptionContainerService} from "../../../../../../base/services/subscription-container.service";
import {DialogService} from "../../../../../common/modules/utility/components/popup/dialog.service";
import {OrganizationService} from "../services/organization.service";
import {EventKey} from "../../../../../../services/eventbus/event.key";
import {IOrganization} from "../models/organization.model";
import {LocalStorageService} from "../../../../../../services/storage/localstorage.service";


export abstract class BaseListComponentForOrg<MODEL, DETAIL_MODEL> extends BaseListComponentV4<MODEL, DETAIL_MODEL> {
  protected orgId: number | null = null

  protected constructor(eventBus: EventBusService,
                        router: Router,
                        subContainer: SubscriptionContainerService,
                        dialog: DialogService<DETAIL_MODEL>,
                        private orgService: OrganizationService
  ) {
    super(eventBus, router, subContainer, dialog)
  }

  protected onOrgLoaded(block: (orgId: number) => void) {
    this.initOrg(() => {
      if (this.orgId != null) {
        block(this.orgId)
      } else {
        this.fetchOrgId(block)
      }
    })
  }

  fetchOrgId(block: (orgId: number) => void) {
    let key = this.componentKey(EventKey.ORGANIZATIONS.GET_MY_ORG())
    this.orgService.fetchMyOrgs(key)
    this.subscribe(key, null, (value, meta) => {
      let orgs = meta.data as IOrganization[]
      if (orgs.length > 0) {
        block(orgs[0].id)
      }
    })
  }

  private initOrg(fn: () => void) {
    LocalStorageService.retrieveAsync('selectedOrg', (orgStr) => {
      let org = orgStr != undefined ? JSON.parse(orgStr) : null
      if (org != null) {
        this.orgId = org.id
      }
      fn()
    })
  }

}
