import {Component} from "@angular/core";
import {defaultTaskConfig, selfEndpoints, selfRoutes, TaskConfig} from "../../models/config.model";
import {
  BasicFilterData,
  defaultFilterData,
  FilterField,
  parseFilterData,
  toParams
} from "../../../../../../common/modules/utility/components/basic-filter/basic-filter.model";
import {defaultPage, IPage} from "../../../../../../../base/models/IPage";
import {EventBusService} from "../../../../../../../services/eventbus/event-bus.service";
import {ActivatedRoute, Router} from "@angular/router";
import {SubscriptionContainerService} from "../../../../../../../base/services/subscription-container.service";
import {AuthService} from "../../../../../../common/modules/auth/services/auth.service";
import {DialogService} from "../../../../../../common/modules/utility/components/popup/dialog.service";
import {TaskService} from "../../services/task.service";
import {NotifierService} from "../../../../../../../services/notifier/notifier.service";
import {BreadcrumbItem} from "../../../../../../common/modules/generic/breadcrumb/breadcrumb.model";
import {IParams} from "../../../../../../../base/endpoints/iparams";
import {EventKey} from "../../../../../../../services/eventbus/event.key";
import {MetaData} from "ng-event-bus/lib/meta-data";
import {BaseConfigV2} from "../../../../../../../base/models/baseConfig";
import {ComponentType} from "@angular/cdk/overlay";
import {TaskUpsertComponent} from "../task-upsert/task-upsert.component";
import {ITask, ITaskDetail} from "../../models/task.model";
import {BaseUpsertComponentV3} from "../../../../../../../base/components/base-upsert-v3.component";
import {IBoard} from "../../../boards/models/board.model";
import {BoardService} from "../../../boards/services/board.service";
import {DashEndpoint} from "../../../../../dash.endpoint";
import {translations} from "../../../../../layout/left-nav/menu.model";
import {TaskStateService} from "../../../taskstates/services/taskstate.service";
import {ITaskState, ITaskStateDetail} from "../../../taskstates/models/taskstate.model";
import {HttpErrorResponse} from "@angular/common/http";
import {DeleteService} from "../../../../../../common/modules/utility/components/delete/services/delete.service";
import {CdkDragDrop, moveItemInArray, transferArrayItem} from "@angular/cdk/drag-drop";
import {TaskStateUpsertComponent} from "../../../taskstates/components/taskstate-upsert/taskstate-upsert.component";
import {Utility} from "../../../../../../common/modules/utility/utility";
import {
  TaskAssignmentUpsertComponent
} from "../../../taskassignments/components/taskassignment-upsert/taskassignment-upsert.component";
import {IAssignee, ITaskAssignment, ITaskAssignmentDetail} from "../../../taskassignments/models/taskassignment.model";
import {BaseListComponentForOrg} from "../../../../mdm/organizations/components/org-base-list.component";
import {OrganizationService} from "../../../../mdm/organizations/services/organization.service";


@Component({
  selector: 'app-task-list',
  templateUrl: './task-list.component.html',
  styleUrls: ['./task-list.component.scss']
})
export class TaskListComponent extends BaseListComponentForOrg<ITask, ITaskDetail> {

  config: TaskConfig = defaultTaskConfig
  filterData: BasicFilterData = defaultFilterData
  filterFields: FilterField[] = []

  tasks: IPage<ITask> = defaultPage

  allTasks: { state: ITaskState, tasks: ITask[] }[] = []

  boards: IBoard[] = []
  selectedBoard: IBoard | null = null

  protected componentName(): string {
    return TaskListComponent.name;
  }

  constructor(eventBus: EventBusService,
              router: Router,
              subContainer: SubscriptionContainerService,
              private authService: AuthService,
              private dialog: DialogService<ITaskDetail>,
              private activatedRoute: ActivatedRoute,
              private taskService: TaskService,
              private notifier: NotifierService,
              orgService: OrganizationService,
              private boardService: BoardService,
              private taskStateService: TaskStateService,
              private deleteService: DeleteService,
              private stateUpsertDialog: DialogService<ITaskStateDetail>,
              private assignmentDialog: DialogService<ITaskAssignmentDetail>
  ) {
    super(eventBus, router, subContainer, dialog, orgService)
    if (authService.isAdmin()) {
      this.config.showUserFilter = true
      this.config.endpoint = selfEndpoints.adminEndpoint
      this.config.delEndpoint = selfEndpoints.adminEndpoint
      this.config.boardEndpoint = DashEndpoint.BOARDS.BOARD_ENDPOINT_ADMIN
      this.config.taskStatesEndpoint = DashEndpoint.TASKSTATES.TASKSTATE_ENDPOINT_ADMIN
    }
  }

  override ngOnInit() {
    super.ngOnInit();

    this.onOrgLoaded(orgId => {
      this.onBoardsLoaded({org_id: orgId, q: null, page: 0, size: 100}, (boards: IPage<IBoard>) => {
        this.boards = boards.content
        this.filterFields = [{
          type: "dropdown",
          label: "Board",
          name: "board_id",
          value: '',
          placeholder: "Select Board",
          options: boards.content.map(board => {
            return {value: board.id, label: board.title}
          })
        }]
      })
    })
  }

  initialize(): void {
    this.activatedRoute.queryParams.subscribe(params => {
      this.filterData = parseFilterData(params)
      let boardId = params['board_id']
      this.selectedBoard = this.boards.find(board => board.id == boardId) ?? null
      let filterParams = {
        board_id: boardId,
        q: this.filterData.query,
        username: this.filterData.username,
        from_date: this.filterData.fromDate,
        to_date: this.filterData.toDate,
        page: this.filterData.page,
        size: this.filterData.size
      }
      this.onOrgLoaded((orgId: number) => {
        this.fetchTaskStates({board_id: boardId, org_id: orgId, q: null, page: 0, size: 100},
          (taskStates: IPage<ITaskState>) => {
            let states = taskStates.content.sort((a, b) => a.order - b.order)
            if (this.authService.isAdmin()) {
              this.fetchTasks(filterParams, (tasks: IPage<ITask>) => {
                this.tasks = tasks
                this.organizeTasks(states, tasks.content)
              })
            } else {
              this.fetchTasks({
                ...filterParams,
                org_id: orgId
              }, (tasks: IPage<ITask>) => {
                this.tasks = tasks
                this.organizeTasks(states, tasks.content)
              })
            }
          })

      })
    });
  }

  protected override getBreadcrumbItems(): BreadcrumbItem[] {
    return [
      {
        text: this.translations["Dashboard"],
        link: null,
        active: false
      },
      {
        text: translations["Task"],
        link: null,
        active: true
      }
    ]
  }

  private onBoardsLoaded(params: IParams, onLoaded: (boards: IPage<IBoard>) => void) {
    this.loading = true
    const key = this.componentKey(EventKey.BOARDS.SEARCH(params))
    this.boardService.search(key, this.config.boardEndpoint, params)
    this.subscribe(
      key,
      null,
      (value: Boolean, meta: MetaData) => {
        let boards = meta.data as IPage<IBoard>
        onLoaded(boards)
        this.loading = false
      })
    this.subscribe(this.getErrorKey(key), null, (value, meta) => {
      this.notifier.error('Error', meta.data.error.error.message)
    })
  }

  private fetchTaskStates(params: IParams, onLoaded: (taskStates: IPage<ITaskState>) => void) {
    this.loading = true
    const key = this.componentKey(EventKey.TASKSTATES.SEARCH(params))
    this.taskStateService.search(key, this.config.taskStatesEndpoint, params)
    this.subscribe(
      key,
      null,
      (value: Boolean, meta: MetaData) => {
        let taskStates = meta.data as IPage<ITaskState>
        this.loading = false
        onLoaded(taskStates)
      })
    this.subscribe(this.getErrorKey(key), null, (value, meta) => {
      this.notifier.error('Error', meta.data.error.message)
    })
  }

  private fetchTasks(params: IParams, onLoaded: (tasks: IPage<ITask>) => void) {
    this.loading = true
    const key = this.componentKey(EventKey.TASKS.SEARCH(params))
    this.taskService.search(key, this.config.endpoint, params)
    this.subscribe(
      key,
      null,
      (value: Boolean, meta: MetaData) => {
        let tasks = meta.data as IPage<ITask>
        this.loading = false
        onLoaded(tasks)
      })
    this.subscribe(this.getErrorKey(key), null, (value, meta) => {
      this.notifier.error('Error', meta.data.error.message)
    })
  }

  onDeleted(deleted: Boolean) {
    if (deleted) {
      this.notifier.success("Success", "Task is deleted")
      this.ngOnInit()
    }
  }

  override getConfig(): BaseConfigV2 {
    return this.config
  }

  override getRoutes(): { create: string, update: (id: number) => string, params: IParams } | null {
    return {
      create: selfRoutes.create,
      update: (id: number) => selfRoutes.update(id),
      params: toParams(this.filterData)
    }
  }

  getUpsertComponent(): ComponentType<BaseUpsertComponentV3<ITaskDetail>> | null {
    return TaskUpsertComponent;
  }

  private organizeTasks(states: ITaskState[], tasks: ITask[]) {
    this.allTasks = states.map(state => {
      return {
        state: state,
        tasks: tasks.filter(task => task.state.id == state.id)
      }
    })
  }

  protected readonly confirm = confirm;

  delete(url: string) {
    let conf = confirm("Are you sure to continue?")
    if (!conf) return
    let key = this.componentKey(url)
    this.deleteService.deleteItem(key, url)

    this.subscribe(key, null, (value, meta) => {
      this.notifier.success("Success", "Task is deleted")
      this.ngOnInit()
    })
    this.subscribe(this.getErrorKey(key), null, (value, meta) => {
      let err: HttpErrorResponse = meta.data
      this.notifier.error('Error!', err.error.message)
    })
  }

  drop(event: CdkDragDrop<ITask[], any>) {
    if (event.previousContainer === event.container) {
      moveItemInArray(event.container.data, event.previousIndex, event.currentIndex);
    } else {
      transferArrayItem(
        event.previousContainer.data,
        event.container.data,
        event.previousIndex,
        event.currentIndex,
      );
    }

    this.allTasks.filter((item, index) => {
      let found = item.tasks.find((task, index) => {
        return task.state.id != item.state.id
      })
      if (found) {
        let taskOrder = event.currentIndex
        console.log('index', taskOrder)
        found.state = item.state
        this.changeState(found.id, item.state)
      }
    })
  }

  private changeState(id: number, newState: ITaskState) {
    let key = this.componentKey(EventKey.TASKS.UPSERT(id))
    this.taskService.changeState(key, id, newState.id)
    this.subscribe(key, null, (value, meta) => {
      this.notifier.success("Success", "Task is moved to " + newState.label)
    })
    this.subscribe(this.getErrorKey(key), null, (value, meta) => {
      let err: HttpErrorResponse = meta.data
      this.notifier.error('Error!', err.error.message)
    })
  }

  onStateEditClick(stateId: number) {
    let dialogRef = this.stateUpsertDialog.open(TaskStateUpsertComponent, {id: stateId})
    this.stateUpsertDialog.onCompleted.subscribe((result: ITaskState | null) => {
      this.ngOnInit()
      dialogRef.close()
      console.log("onSuccess. closing dialog")
    })
    this.stateUpsertDialog.onCanceled.subscribe(() => {
      dialogRef.close()
      console.log("onCanceled. closing dialog")
    })
  }

  addNew(state: ITaskState) {
    let upsertComponent = this.getUpsertComponent()
    if (upsertComponent == null) {
      return
    }
    this.dialog.open(upsertComponent, {id: null, board: this.selectedBoard, state: state})
    this.dialog.onCompleted.subscribe((result: ITask | null) => {
      this.ngOnInit()
      if (result != null) {
        this.onUpsertSuccess(result)
      }
    })
    this.dialog.onCanceled.subscribe(() => {
    })
  }

  protected readonly Utility = Utility;

  getInvertedColor(color: string | null) {
    return Utility.invertColor(color ?? '#FFFFFF', true);
  }

  getAssignees(task: ITask): IAssignee[] {
    return task.assignments.map(a => a.assignee)
  }

  upsertAssignment(event: Event, task: ITask, assignment: ITaskAssignment | null) {
    event.stopPropagation()
    this.assignmentDialog.open(TaskAssignmentUpsertComponent, {id: null, task: task, assignee: assignment?.assignee})
    this.assignmentDialog.onCompleted.subscribe((result: ITask | null) => {
      this.ngOnInit()
      if (result != null) {
        this.onUpsertSuccess(result)
      }
    })
    this.assignmentDialog.onCanceled.subscribe(() => {
    })
  }

  removeAssignment(task: ITask, assignment: ITaskAssignment) {
    if (!confirm("Are you sure you wanna remove this assignment?")) return
    let key = this.componentKey(EventKey.TASKS.REMOVE_ASSIGNMENT(task.id, assignment.assignee.id))
    this.taskService.remove(key, task.id, assignment.assignee.id)
    this.subscribe(key, null, (v, meta) => {
      let removed = meta.data as Boolean
      if (removed) {
        this.notifier.success("Removed", "Successfully removed assignment.")
        this.ngOnInit()
      } else {
        this.notifier.warning("Failed", "Couldn't remove assignment.")
      }
    })
    this.subscribe(this.getErrorKey(key), null, (value, meta) => {
      let err: HttpErrorResponse = meta.data
      this.notifier.error('Error!', err.error.error.message)
    })
    console.log("task", task, "assignment", assignment)
  }

  showDetails(event: MouseEvent, id: number, edit: boolean) {
    event.stopImmediatePropagation()
    this.onUpsertClick(id, edit)
  }

}
