import {Component, Inject} from "@angular/core";
import {BaseUpsertComponentV3} from "../../../../../../../base/components/base-upsert-v3.component";
import {defaultSearchHistoryConfig, SearchHistoryConfig, selfEndpoints, selfRoutes} from "../../models/config.model";
import {FormControl, FormGroup, Validators} from "@angular/forms";
import {EventBusService} from "../../../../../../../services/eventbus/event-bus.service";
import {ActivatedRoute, Router} from "@angular/router";
import {SubscriptionContainerService} from "../../../../../../../base/services/subscription-container.service";
import {SearchHistoryService} from "../../services/searchhistory.service";
import {NotifierService} from "../../../../../../../services/notifier/notifier.service";
import {AuthService} from "../../../../../../common/modules/auth/services/auth.service";
import {BreadcrumbItem} from "../../../../../../common/modules/generic/breadcrumb/breadcrumb.model";
import {EventKey} from "../../../../../../../services/eventbus/event.key";
import {HttpErrorResponse} from "@angular/common/http";
import {BaseConfigV2} from "../../../../../../../base/models/baseConfig";
import {ISearchHistoryDetail, ISearchHistoryReq} from "../../models/searchhistory.model";
import {MAT_DIALOG_DATA} from "@angular/material/dialog";


@Component({
  selector: 'app-searchhistory-upsert',
  templateUrl: './searchhistory-upsert.component.html',
  styleUrls: ['./searchhistory-upsert.component.scss']
})
export class SearchHistoryUpsertComponent extends BaseUpsertComponentV3<ISearchHistoryDetail> {

  config: SearchHistoryConfig = defaultSearchHistoryConfig

  searchHistoryForm = new FormGroup({
    entity_name: new FormControl('', [Validators.required, Validators.minLength(3)]),
    query: new FormControl('', [Validators.required, Validators.minLength(3)]),
  })

  constructor(eventBus: EventBusService,
              router: Router,
              subContainer: SubscriptionContainerService,
              route: ActivatedRoute,
              private searchHistoryService: SearchHistoryService,
              private notifier: NotifierService,
              authService: AuthService,
              @Inject(MAT_DIALOG_DATA) dialogData: any) {
    super(eventBus, router, subContainer, route, dialogData)

    if (authService.isAdmin()) {
      this.config.endpoint = selfEndpoints.adminEndpoint
      this.config.delEndpoint = selfEndpoints.adminEndpoint
    }

    if (dialogData.title != null) {
      this.searchHistoryForm.controls.entity_name.setValue(dialogData.title)
    }

  }

  protected override componentName(): string {
    return SearchHistoryUpsertComponent.name
  }

  protected override getBreadcrumbItems(): BreadcrumbItem[] {
    return [
      {
        text: this.translations["Dashboard"],
        link: null,
        active: false
      },
      {
        text: this.translations["Search Histories"],
        link: "/dash/search-histories",
        active: false
      },
      {
        text: this.translations["Upsert"],
        link: null,
        active: true
      }
    ]
  }

  override initialize(exId: number): void {
    this.loading = true
    let key = this.componentKey(EventKey.SEARCHHISTORIES.GET(exId))
    this.searchHistoryService.fetchSingle(key, this.config.endpoint, exId)
    this.subscribe(key, null, (value, meta) => {
      this.loading = false;
      this.populateForm(meta.data)
    })
    this.subscribe(this.getErrorKey(key), null, (value, meta) => {
      let error: HttpErrorResponse = meta.data
      console.log(error)
      this.loading = false;
    })
  }

  onSubmit() {
    if (!this.searchHistoryForm.valid) {
      return
    }
    this.upsert(this.exId)
  }

  getConfig(): BaseConfigV2 {
    return this.config;
  }

  getListPageRoute(): string {
    return selfRoutes.list;
  }

  upsert(exId: number | null) {
    this.loading = true
    let key = this.componentKey(EventKey.SEARCHHISTORIES.UPSERT(exId))
    let req = this.searchHistoryForm.value as ISearchHistoryReq
    this.searchHistoryService.upsert(key, this.config.endpoint, req, exId)
    this.subscribe(key, null, (value, meta) => {
      this.notifier.success("Success", "SearchHistory has been " + (exId ? "updated" : "created"))
      this.searchHistoryForm.reset();
      this.onSuccess(meta.data)
    })
    this.subscribe(this.getErrorKey(key), null, (value, meta) => {
      let error: HttpErrorResponse = meta.data
      this.loading = false;
      this.notifier.warning('Failed!', error.error.message)
    })
  }

  private populateForm(n: ISearchHistoryDetail) {
    this.searchHistoryForm.controls.entity_name.setValue(n.entity_name)
    this.searchHistoryForm.controls.query.setValue(n.query)
  }

}
