import {Component, Inject} from '@angular/core';
import {FormControl, FormGroup, Validators} from "@angular/forms";
import {BaseUpsertComponentV3} from "../../../../../../../base/components/base-upsert-v3.component";
import {BoardConfig, defaultBoardConfig, selfEndpoints, selfRoutes} from "../../models/config.model";
import {EventBusService} from "../../../../../../../services/eventbus/event-bus.service";
import {ActivatedRoute, Router} from "@angular/router";
import {SubscriptionContainerService} from "../../../../../../../base/services/subscription-container.service";
import {BoardService} from "../../services/board.service";
import {NotifierService} from "../../../../../../../services/notifier/notifier.service";
import {AuthService} from "../../../../../../common/modules/auth/services/auth.service";
import {MAT_DIALOG_DATA} from "@angular/material/dialog";
import {BreadcrumbItem} from "../../../../../../common/modules/generic/breadcrumb/breadcrumb.model";
import {EventKey} from "../../../../../../../services/eventbus/event.key";
import {HttpErrorResponse} from "@angular/common/http";
import {IImageSlice} from "../../../../../../common/modules/cms/files/models/file.model";
import {BaseConfigV2} from "../../../../../../../base/models/baseConfig";
import {IBoardDetail, IBoardReq} from "../../models/board.model";
import {TextUtility} from "../../../../../../common/modules/utility/text.utility";
import {IOrganization} from "../../../../mdm/organizations/models/organization.model";

@Component({
  selector: 'app-board-upsert',
  templateUrl: './board-upsert.component.html',
  styleUrls: ['./board-upsert.component.scss']
})
export class BoardUpsertComponent extends BaseUpsertComponentV3<IBoardDetail> {

  config: BoardConfig = defaultBoardConfig

  selectedOrg: IOrganization | null = null

  boardForm = new FormGroup({
    title: new FormControl('', [Validators.required, Validators.minLength(3), Validators.maxLength(30)]),
    code: new FormControl<string | null>(null, [
      Validators.required, Validators.minLength(3), Validators.maxLength(30)
    ]),
    description: new FormControl('', [Validators.required, Validators.minLength(20)]),
    image: new FormControl<string | null>(null),
    public: new FormControl<boolean>(false),
    organization_id: new FormControl<number | null>(null, [Validators.required]),
  })

  constructor(eventBus: EventBusService,
              router: Router,
              subContainer: SubscriptionContainerService,
              route: ActivatedRoute,
              private boardService: BoardService,
              private notifier: NotifierService,
              authService: AuthService,
              @Inject(MAT_DIALOG_DATA) dialogData: any) {
    super(eventBus, router, subContainer, route, dialogData)

    if (authService.isAdmin()) {
      this.config.endpoint = selfEndpoints.adminEndpoint
      this.config.delEndpoint = selfEndpoints.adminEndpoint
    }

    if (dialogData.title != null) {
      this.boardForm.controls.title.setValue(dialogData.title)
    }

  }

  override ngOnInit() {
    super.ngOnInit();
    this.boardForm.controls.title.valueChanges.subscribe(value => {
      this.boardForm.controls.code.setValue(
        TextUtility.codify(value)
      )
    })
  }

  protected override componentName(): string {
    return BoardUpsertComponent.name
  }

  protected override getBreadcrumbItems(): BreadcrumbItem[] {
    return [
      {
        text: this.translations["Dashboard"],
        link: null,
        active: false
      },
      {
        text: "Boards",
        link: "/dash/boards",
        active: false
      },
      {
        text: "Upsert",
        link: null,
        active: true
      }
    ]
  }

  override initialize(exId: number): void {
    this.loading = true
    let key = this.componentKey(EventKey.BOARDS.GET(exId))
    this.boardService.fetchSingle(key, this.config.endpoint, exId)
    this.subscribe(key, null, (value, meta) => {
      this.loading = false;
      this.populateForm(meta.data)
    })
    this.subscribe(this.getErrorKey(key), null, (value, meta) => {
      let error: HttpErrorResponse = meta.data
      console.log(error)
      this.loading = false;
    })
  }

  onSubmit() {
    if (!this.boardForm.valid) {
      return
    }
    this.upsert(this.exId)
  }

  onImgUploaded(images: IImageSlice[]) {
    if (images.length > 0) {
      /*
      Think about the thumbnail, this will only upload the image, not thumbnail
       */
      this.boardForm.controls.image.setValue(images[0].image_url)
    }
  }

  getExImages(): IImageSlice[] {
    let image = this.boardForm.controls.image.value
    if (image == null) {
      return []
    }
    return [{image_url: image, thumb_url: image}]
  }

  getConfig(): BaseConfigV2 {
    return this.config;
  }

  getListPageRoute(): string {
    return selfRoutes.list;
  }

  upsert(exId: number | null) {
    this.loading = true
    let key = this.componentKey(EventKey.BOARDS.UPSERT(exId))
    let req = this.boardForm.value as IBoardReq
    this.boardService.upsert(key, this.config.endpoint, req, exId)
    this.subscribe(key, null, (value, meta) => {
      this.notifier.success("Success", "Board has been " + (exId ? "updated" : "created"))
      this.boardForm.reset();
      this.onSuccess(meta.data)
    })
    this.subscribe(this.getErrorKey(key), null, (value, meta) => {
      let error: HttpErrorResponse = meta.data
      this.loading = false;
      this.notifier.warning('Failed!', error.error.error.message)
    })
  }

  private populateForm(n: IBoardDetail) {
    this.selectedOrg = n.organization

    this.boardForm.controls.title.setValue(n.title)
    this.boardForm.controls.description.setValue(n.description)
    this.boardForm.controls.image.setValue(n.image == null ? null : n.image)
    this.boardForm.controls.code.setValue(n.code)
    this.boardForm.controls.public.setValue(n.public)
    this.boardForm.controls.organization_id.setValue(n.organization.id)
  }

  onOrgSelected(org: IOrganization | null) {
    this.selectedOrg = org
    this.boardForm.controls.organization_id.setValue(org?.id ?? null)
  }

}
