import {Injectable} from '@angular/core';
import {BaseService} from "../../../../../../base/services/base.service";
import {AuthService} from "../../../../../common/modules/auth/services/auth.service";
import {NotifierService} from "../../../../../../services/notifier/notifier.service";
import {HttpClient, HttpErrorResponse} from "@angular/common/http";
import {EventBusService} from "../../../../../../services/eventbus/event-bus.service";
import {IParams} from "../../../../../../base/endpoints/iparams";
import {DashEndpoint} from "../../../../dash.endpoint";
import {IPage, ResponseData} from "../../../../../../base/models/IPage";
import {IAuth} from "../../../../../common/modules/auth/models/auth.model";
import {ITask, ITaskActivity, ITaskDetail, ITaskReq} from "../models/task.model";

@Injectable({
  providedIn: 'root'
})
export class TaskService extends BaseService {

  constructor(
    authService: AuthService,
    notifier: NotifierService,
    private http: HttpClient,
    private eventBusService: EventBusService
  ) {
    super(authService, notifier)
  }

  search(key: string, endpoint: string, params: IParams) {
    let url = DashEndpoint.TASKS.SEARCH(endpoint, params)
    this.http.get<ResponseData<IPage<ITask>>>(url)
      .subscribe((data: ResponseData<IPage<ITask>>) => {
        this.eventBusService.publish(key, data.body)
      }, error => {
        this.handleError(error, (auth: IAuth) => {
          this.search(key, endpoint, params)
        }, (err: HttpErrorResponse) => {
          this.eventBusService.publish(this.getErrorKey(key), err)
        })
      })
  }

  fetchSingle(key: string, endpoint: string, id: number) {
    this.http.get<ResponseData<ITask>>(DashEndpoint.TASKS.GET(endpoint, id))
      .subscribe((data: ResponseData<ITask>) => {
        this.eventBusService.publish(key, data.body)
      }, (error: HttpErrorResponse) => {
        this.handleError(error, (auth: IAuth) => {
          this.fetchSingle(key, endpoint, id)
        }, (err: HttpErrorResponse) => {
          this.eventBusService.publish(this.getErrorKey(key), err)
        })
      })
  }

  upsert(key: string, endpoint: string, taskReq: ITaskReq, exId: number | null) {
    let url = exId == null ? DashEndpoint.TASKS.CREATE(endpoint)
      : DashEndpoint.TASKS.UPDATE(endpoint, exId)

    let observable = exId == null ?
      this.http.post<ResponseData<ITaskDetail>>(url, taskReq)
      : this.http.patch<ResponseData<ITaskDetail>>(url, taskReq)

    observable.subscribe(res => {
      this.eventBusService.publish(key, res.body)
    }, (err: HttpErrorResponse) => {
      this.handleError(err, (auth: IAuth) => {
        this.upsert(key, endpoint, taskReq, exId)
      }, (err: HttpErrorResponse) => {
        this.eventBusService.publish(this.getErrorKey(key), err)
      })
    })
  }

  changeState(key: string, id: number, stateId: number) {
    let endpoint = DashEndpoint.TASKS.TASK_ENDPOINT
    let url = DashEndpoint.TASKS.CHANGE_STATE(endpoint, id, {state_id: stateId})
    this.http.patch<ResponseData<ITaskDetail>>(url, null)
      .subscribe(res => {
        this.eventBusService.publish(key, res.body)
      }, (err: HttpErrorResponse) => {
        this.handleError(err, (auth: IAuth) => {
          this.changeState(key, id, stateId);
        }, (err: HttpErrorResponse) => {
          this.eventBusService.publish(this.getErrorKey(key), err)
        })
      })
  }

  remove(key: string, taskId: number, assignmentId: number) {
    this.http.delete<ResponseData<Boolean>>(DashEndpoint.TASKASSIGNMENTS.REMOVE_ASSIGNMENT(taskId, assignmentId))
      .subscribe((data: ResponseData<Boolean>) => {
        this.eventBusService.publish(key, data.body)
      }, (error: HttpErrorResponse) => {
        this.handleError(error, (auth: IAuth) => {
          this.remove(key, taskId, assignmentId)
        }, (err: HttpErrorResponse) => {
          this.eventBusService.publish(this.getErrorKey(key), err)
        })
      })
  }

  /*
  Load Activities
   */

  searchTaskActivities(key: string, taskId: number, params: IParams) {
    let url = DashEndpoint.TASKS.SEARCH_TASK_ACTIVITIES(taskId, params)
    this.http.get<ResponseData<IPage<ITaskActivity>>>(url)
      .subscribe((data: ResponseData<IPage<ITaskActivity>>) => {
        this.eventBusService.publish(key, data.body)
      }, error => {
        this.handleError(error, (auth: IAuth) => {
          this.searchTaskActivities(key, taskId, params)
        }, (err: HttpErrorResponse) => {
          this.eventBusService.publish(this.getErrorKey(key), err)
        })
      })
  }
}
