import {Component, Inject, ViewChild} from "@angular/core";
import {BaseUpsertComponentV3} from "../../../../../../../base/components/base-upsert-v3.component";
import {BlogMenuConfig, defaultBlogMenuConfig, selfEndpoints, selfRoutes} from "../../models/config.model";
import {FormControl, FormGroup, Validators} from "@angular/forms";
import {EventBusService} from "../../../../../../../services/eventbus/event-bus.service";
import {ActivatedRoute, Router} from "@angular/router";
import {SubscriptionContainerService} from "../../../../../../../base/services/subscription-container.service";
import {BlogMenuService} from "../../services/blogmenu.service";
import {NotifierService} from "../../../../../../../services/notifier/notifier.service";
import {AuthService} from "../../../../../../common/modules/auth/services/auth.service";
import {BreadcrumbItem} from "../../../../../../common/modules/generic/breadcrumb/breadcrumb.model";
import {EventKey} from "../../../../../../../services/eventbus/event.key";
import {HttpErrorResponse} from "@angular/common/http";
import {IImageSlice} from "../../../../../../common/modules/cms/files/models/file.model";
import {BaseConfigV2} from "../../../../../../../base/models/baseConfig";
import {IBlogMenu, IBlogMenuDetail, IBlogMenuReq} from "../../models/blogmenu.model";
import {MAT_DIALOG_DATA} from "@angular/material/dialog";
import {IBlog} from "../../../blogs/models/blog.model";
import {BlogMenuSelectComponent} from "../blogmenu-select/blogmenu-select.component";

@Component({
  selector: 'app-blogmenu-upsert',
  templateUrl: './blogmenu-upsert.component.html',
  styleUrls: ['./blogmenu-upsert.component.scss']
})
export class BlogMenuUpsertComponent extends BaseUpsertComponentV3<IBlogMenuDetail> {
  @ViewChild("parentSelect") parentSelect: BlogMenuSelectComponent

  config: BlogMenuConfig = defaultBlogMenuConfig

  selectedBlog: IBlog | null = null
  selectedParent: IBlogMenu | null = null

  blogMenuForm = new FormGroup({
    title: new FormControl('', [Validators.required, Validators.minLength(3)]),
    description: new FormControl('', [Validators.required, Validators.minLength(3), Validators.maxLength(255)]),
    image: new FormControl<string | null>(null),
    link: new FormControl<string>('', [Validators.required, Validators.minLength(3), Validators.maxLength(255)]),
    type: new FormControl<string>('BLOG'),
    parent_id: new FormControl<number | null>(null),
    blog_id: new FormControl<number | null>(null, [Validators.required])
  })

  constructor(eventBus: EventBusService,
              router: Router,
              subContainer: SubscriptionContainerService,
              route: ActivatedRoute,
              private blogMenuService: BlogMenuService,
              private notifier: NotifierService,
              authService: AuthService,
              @Inject(MAT_DIALOG_DATA) dialogData: any) {
    super(eventBus, router, subContainer, route, dialogData)

    this.blogMenuForm.controls.link.valueChanges.subscribe(value => {
      this.blogMenuForm.controls.link.setValue(value?.trim()??"")
    })

    if (authService.isAdmin()) {
      this.config.endpoint = selfEndpoints.adminEndpoint
      this.config.delEndpoint = selfEndpoints.adminEndpoint
    }

    if (dialogData.title != null) {
      this.blogMenuForm.controls.title.setValue(dialogData.title)
    }

  }

  onBlogSelected(blog: IBlog | null) {
    this.selectedBlog = blog
    this.blogMenuForm.controls.blog_id.setValue(blog?.id ?? null)
    this.parentSelect.clear()
    this.parentSelect.search({
      page: 0, size: 10, q: null, 'blog_slug': blog?.slug
    })
  }

  onParentSelected(menu: IBlogMenu | null) {
    this.selectedParent = menu
    this.blogMenuForm.controls.parent_id.setValue(menu?.id ?? null)
  }

  protected override componentName(): string {
    return BlogMenuUpsertComponent.name
  }

  protected override getBreadcrumbItems(): BreadcrumbItem[] {
    return [
      {
        text: this.translations["Dashboard"],
        link: null,
        active: false
      },
      {
        text: "BlogMenus",
        link: "/dash/blogmenus",
        active: false
      },
      {
        text: this.translations["Upsert"],
        link: null,
        active: true
      }
    ]
  }

  override initialize(exId: number): void {
    this.loading = true
    let key = this.componentKey(EventKey.BLOGMENUS.GET(exId))
    this.blogMenuService.fetchSingle(key, this.config.endpoint, exId)
    this.subscribe(key, null, (value, meta) => {
      this.loading = false;
      this.populateForm(meta.data)
    })
    this.subscribe(this.getErrorKey(key), null, (value, meta) => {
      let error: HttpErrorResponse = meta.data
      console.log(error)
      this.loading = false;
    })
  }

  onSubmit() {
    if (!this.blogMenuForm.valid) {
      return
    }
    this.upsert(this.exId)
  }

  onImgUploaded(images: IImageSlice[]) {
    if (images.length > 0) {
      /*
      Think about the thumbnail, this will only upload the image, not thumbnail
       */
      this.blogMenuForm.controls.image.setValue(images[0].image_url)
    }
  }

  getExImages(): IImageSlice[] {
    let image = this.blogMenuForm.controls.image.value
    if (image == null) {
      return []
    }
    return [{image_url: image, thumb_url: image}]
  }

  getConfig(): BaseConfigV2 {
    return this.config;
  }

  getListPageRoute(): string {
    return selfRoutes.list;
  }

  upsert(exId: number | null) {
    this.loading = true
    let key = this.componentKey(EventKey.BLOGMENUS.UPSERT(exId))
    let req = this.blogMenuForm.value as IBlogMenuReq
    this.blogMenuService.upsert(key, this.config.endpoint, req, exId)
    this.subscribe(key, null, (value, meta) => {
      this.notifier.success("Success", "BlogMenu has been " + (exId ? "updated" : "created"))
      this.blogMenuForm.reset();
      this.onSuccess(meta.data)
    })
    this.subscribe(this.getErrorKey(key), null, (value, meta) => {
      let error: HttpErrorResponse = meta.data
      this.loading = false;
      this.notifier.warning('Failed!', error.error.message)
    })
  }

  private populateForm(n: IBlogMenuDetail) {
    this.selectedParent = n.parent
    this.selectedBlog = n.blog

    this.blogMenuForm.controls.title.setValue(n.title)
    this.blogMenuForm.controls.description.setValue(n.description)
    this.blogMenuForm.controls.image.setValue(n.image == null ? null : n.image)
    this.blogMenuForm.controls.link.setValue(n.link)
    this.blogMenuForm.controls.type.setValue(n.type)
    this.blogMenuForm.controls.parent_id.setValue(n.parent?.id ?? null)
    this.blogMenuForm.controls.blog_id.setValue(n.blog?.id ?? null)
  }

}
