import {DashEndpoint} from "../../../../dash.endpoint";
import {BaseConfigV2} from "../../../../../../base/models/baseConfig";
import {Layout} from "../../../../../common/modules/generic/breadcrumb/breadcrumb.model";

export let selfEndpoints = {
  endpoint: DashEndpoint.TASKSTATES.TASKSTATE_ENDPOINT,
  adminEndpoint: DashEndpoint.TASKSTATES.TASKSTATE_ENDPOINT_ADMIN,
}

export interface TaskStateConfig extends BaseConfigV2 {
  boardEndpoint: string
}

export let defaultTaskStateConfig: TaskStateConfig = {
  defaultLayout: Layout.GRID,
  upsertOnDialog: true,
  showUserFilter: false,
  showDeleteButton: true,
  endpoint: selfEndpoints.endpoint,
  delEndpoint: selfEndpoints.endpoint,
  boardEndpoint: DashEndpoint.BOARDS.BOARD_ENDPOINT
}

export let selfRoutes = {
  list: "/dash/task-states",
  create: "/dash/task-states/create",
  update(id: number | null) {
    return id == null ? this.create : "/dash/task-states/" + id + '/update'
  }
}
